<template>
 <view class="detail-page"><NativeStatusSpacer/><view class="topbar"><button @tap="back">‹</button><text>成长小主人详情</text><view/></view><view class="paper">
 <view v-if="loading" class="state">正在加载</view><view v-else-if="error" class="state error"><text>{{error}}</text><button @tap="initialize">重试</button></view>
 <template v-if="child"><view class="profile"><view class="avatar"><PrototypeIcon name="user" tone="green" :size="56"/></view><text class="name">{{child.studentName}}</text><text class="badge">{{child.status==='ACTIVE'?'在读':child.status==='INACTIVE'?'已离校':child.status}}</text></view><view class="card"><view class="field"><text>学号</text><text>{{child.studentNumber || '未设置'}}</text></view><view class="field"><text>年级</text><text>{{child.gradeNames || '未分配'}}</text></view><view class="field"><text>班级</text><text>{{child.classNames || '未分配'}}</text></view></view>
 <button v-if="canTransferResponsibility" class="transfer-entry" @tap="openResponsibilityTransfer">转交成长负责人 ›</button><template v-if="canReadResponsibility"><view class="card"><text class="title">成长负责人</text><view v-if="responsibilityError" class="state error"><text>{{responsibilityError}}</text><button @tap="initialize">重试</button></view><template v-else-if="responsibility"><text class="responsible-name">{{responsibility.responsibleUser?.name || '暂未分配'}}</text><text class="muted">{{sourceLabel}} · {{availabilityLabel}}</text></template></view><view class="card"><text class="title">负责人交接记录</text><view v-for="record in historyRows" :key="historyKey(record)" class="history"><text>{{record.fromName || '未分配'}} → {{record.toName || '姓名未提供'}}</text><text class="muted">{{record.createdAt}}</text><text class="muted">{{reasonLabels[record.reasonType] || record.reasonType}}{{record.reasonText ? ' · '+record.reasonText : ''}}</text><text v-if="record.operatorName" class="muted">操作人：{{record.operatorName}}</text></view><view v-if="historyLoading" class="state">正在加载记录</view><view v-else-if="historyError" class="state error"><text>{{historyError}}</text><button @tap="loadHistory">重试</button></view><view v-else-if="!historyRows.length" class="state">暂无交接记录</view><view v-else-if="!historyHasMore" class="state">已加载全部</view></view></template>
 </template></view></view>
</template>
<script setup lang="ts">
import {ref,computed} from 'vue';
import {onLoad,onShow,onHide,onUnload,onReachBottom} from '@dcloudio/uni-app';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';
import PrototypeIcon from '@/components/PrototypeIcon.vue';
import {institutionDirectoryApi,type DirectoryChild} from '@/api/institution-directory';
import {responsibilityApi,type StudentResponsibility,type ResponsibilityHistory} from '@/api/student-responsibility';
import {request} from '@/api/http';
import {getMiniappCapabilities} from '@/api/capability';
import {getOrganizationSession} from '@/session/organization-session';
const child=ref<DirectoryChild|null>(null),responsibility=ref<StudentResponsibility|null>(null),historyRows=ref<ResponsibilityHistory[]>([]);
const canTransferResponsibility=ref(false);
const loading=ref(false),error=ref(''),responsibilityError=ref(''),canReadResponsibility=ref(false),historyLoading=ref(false),historyError=ref(''),historyPage=ref(0),historyHasMore=ref(false);
let studentId='',token='',institutionId='',visible=false,revision=0;
const reasonLabels:Record<string,string>={WORK_ADJUSTMENT:'工作调整',RESIGNATION_HANDOVER:'离职交接',TEMPORARY_TAKEOVER:'临时代管',OTHER:'其他'};
const sourceLabel=computed(()=>({ASSIGNED:'指定负责人',HEAD_TEACHER:'班主任',NONE:'未分配'}[responsibility.value?.source||'NONE']));
const availabilityLabel=computed(()=>({AVAILABLE:'可用',UNAVAILABLE:'不可用',UNASSIGNED:'未分配'}[responsibility.value?.availability||'UNASSIGNED']));
function selection(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function sameScope(){const s=selection();return !!token&&getOrganizationSession()?.accessToken===token&&s?.accessToken===token&&s.organizationId===institutionId&&['SCHOOL','TRAINING_INSTITUTION'].includes(s.typeCode||'');}
function current(n:number){return visible&&revision===n&&sameScope();}
function clear(){child.value=null;responsibility.value=null;historyRows.value=[];canReadResponsibility.value=false;canTransferResponsibility.value=false;historyPage.value=0;historyHasMore.value=false;historyLoading.value=false;historyError.value='';responsibilityError.value='';error.value='';}
async function initialize(){visible=true;const n=++revision;token=getOrganizationSession()?.accessToken||'';institutionId=selection()?.organizationId||'';clear();loading.value=true;
 if(!sameScope()||!studentId){error.value='请选择机构并从学员目录打开详情';loading.value=false;return;}try{const [me,cap]=await Promise.all([request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}}),getMiniappCapabilities()]);if(!current(n))return;if(!me.permissionCodes.includes('STUDENT_READ')||cap.classManagementEnabled!==true)throw Error('当前账号没有学员查看权限或功能未启用');
 const result=await institutionDirectoryApi.detail(token,studentId,institutionId);if(!current(n))return;child.value=result;canReadResponsibility.value=me.permissionCodes.includes('STUDENT_RESPONSIBILITY_READ');canTransferResponsibility.value=canReadResponsibility.value&&me.permissionCodes.includes('STUDENT_RESPONSIBILITY_TRANSFER');if(canReadResponsibility.value){historyHasMore.value=true;await Promise.all([loadResponsibility(n),loadHistory()]);}
 }catch(e){if(current(n))error.value=e instanceof Error?e.message:'加载失败';}finally{if(current(n))loading.value=false;}}
async function loadResponsibility(n:number){try{const result=await responsibilityApi.current(token,studentId,institutionId);if(current(n))responsibility.value=result;}catch(e){if(current(n))responsibilityError.value=e instanceof Error?e.message:'负责人加载失败';}}
function historyKey(item:ResponsibilityHistory){return `${item.afterVersionNo}:${item.toUserId}:${item.createdAt}`;}
async function loadHistory(){if(!current(revision)||!canReadResponsibility.value||historyLoading.value||!historyHasMore.value)return;const n=revision,next=historyPage.value+1;historyLoading.value=true;historyError.value='';try{const result=await responsibilityApi.history(token,studentId,institutionId,next);if(!current(n))return;const seen=new Set(historyRows.value.map(historyKey));const added=result.items.filter(item=>{const key=historyKey(item);if(seen.has(key))return false;seen.add(key);return true;});historyRows.value=[...historyRows.value,...added];historyPage.value=next;historyHasMore.value=result.items.length>0&&next*Math.max(1,result.pageSize||20)<result.total;}catch(e){if(current(n))historyError.value=e instanceof Error?e.message:'记录加载失败';}finally{if(current(n))historyLoading.value=false;}}
function hide(){visible=false;++revision;clear();loading.value=false;}
function openResponsibilityTransfer(){if(current(revision)&&canTransferResponsibility.value&&child.value)uni.navigateTo({url:'/pages/student-responsibility-transfer/student-responsibility-transfer?studentId='+encodeURIComponent(studentId)});}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/institution-student-list/institution-student-list'})});}
onLoad(query=>{studentId=typeof query?.studentId==='string'?query.studentId:'';});onShow(initialize);onHide(hide);onUnload(hide);onReachBottom(()=>{if(!historyError.value)void loadHistory();});
</script>
<style scoped>
.transfer-entry{margin:0 0 22rpx;padding:22rpx;border-radius:18rpx;background:#e6f0e1;color:#17684f;font-size:27rpx;text-align:left}.detail-page{min-height:100vh;background:#17684f;color:#193e30}.topbar{height:86rpx;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;color:white;font-size:32rpx;font-weight:650}.topbar button{margin:0;padding:0;width:48rpx;background:transparent;color:white;font-size:48rpx;line-height:72rpx}.topbar>view{width:48rpx}.paper{min-height:calc(100vh - 130rpx);box-sizing:border-box;padding:30rpx 24rpx 60rpx;border-radius:30rpx 30rpx 0 0;background:#f8faf5}.profile{display:flex;align-items:center;gap:18rpx;padding:16rpx 8rpx 32rpx;flex-wrap:wrap}.avatar{width:100rpx;height:100rpx;background:#e5f1e4;border-radius:50%;display:flex;align-items:center;justify-content:center}.name{font-size:36rpx;font-weight:650;overflow-wrap:anywhere}.badge{background:#e5f0e4;color:#287951;font-size:23rpx;border-radius:10rpx;padding:6rpx 14rpx}.card{background:#fffef9;border:1rpx solid #e4eadd;border-radius:24rpx;padding:26rpx;margin-bottom:22rpx}.field{display:flex;justify-content:space-between;gap:24rpx;padding:20rpx 0;font-size:27rpx;border-bottom:1rpx solid #eef1e8}.field:last-child{border:0}.field>text:first-child{color:#7d897c;flex-shrink:0}.field>text:last-child{text-align:right;overflow-wrap:anywhere}.title{display:block;font-size:29rpx;font-weight:650;margin-bottom:24rpx}.responsible-name{display:block;font-size:32rpx;margin-bottom:12rpx}.muted{display:block;font-size:23rpx;color:#7c897c;line-height:1.7;margin-top:6rpx}.history{font-size:27rpx;padding:22rpx 0;border-top:1rpx solid #edf1e6;overflow-wrap:anywhere}.state{padding:28rpx 6rpx;color:#86917f;font-size:25rpx;text-align:center;display:flex;flex-direction:column;gap:16rpx}.error{color:#b05c48}button::after{border:0}.state button{font-size:24rpx;background:#eaf3e7;color:#17684f}
</style>

